### Throttle jobs with identical jobId in BullMQ

Source: https://github.com/taskforcesh/bullmq/blob/master/docs/gitbook/patterns/throttle-jobs.md

Use this BullMQ example to throttle jobs by setting an identical `jobId` in `JobsOptions.jobId`. The queue treats jobs with the same `jobId` as duplicates and only adds the first one, so multiple `add` calls with the same ID result in a single job. Be aware that if `removeOnComplete` or `removeOnFailed` is used, a removed job will not count as existing and a new job with the same ID could be added.

```typescript
import { Job, Queue, Worker } from 'bullmq';

const myQueue = new Queue('Paint');

const worker = new Worker('Paint', async (job: Job) => {
  console.log('Do something with job');
  return 'some value';
});

worker.on('completed', (job: Job, returnvalue: any) => {
  console.log('worker done painting', new Date());
});

worker.on('failed', (job: Job, error: Error) => {
  console.error('worker fail painting', job, error, new Date());
});

// Add only one job that will be delayed at least 1 second.
myQueue.add('house', { color: 'white' }, { delay: 1000, jobId: 'house' });
myQueue.add('house', { color: 'white' }, { delay: 1000, jobId: 'house' });
myQueue.add('house', { color: 'white' }, { delay: 1000, jobId: 'house' });
myQueue.add('house', { color: 'white' }, { delay: 1000, jobId: 'house' });
myQueue.add('house', { color: 'white' }, { delay: 1000, jobId: 'house' });
myQueue.add('house', { color: 'white' }, { delay: 1000, jobId: 'house' });
myQueue.add('house', { color: 'white' }, { delay: 1000, jobId: 'house' });
```

